fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);
    
    if n == 1 {
        // If there's only one element, return it as is.
        result.push(a[0]);
    } else {
        // Push the last element of the input as the first element of the result.
        result.push(a[n - 1]);
        
        // Copy the interior elements.
        for i in 1..n - 1 {
            result.push(a[i]);
        }
        
        // Push the first element of the input as the last element of the result.
        result.push(a[0]);
    }
    
    result
}